      const now = Date.now();

      if (video.currentTime !== lastTime) {
        lastTime = video.currentTime;
        lastProgressAt = now;
        recoveries = 0;
      }

      // Should be playing but isn't (occlusion suspension, silent pause)
      if (wantsPlay && video.paused && !video.ended) {
        log('should be playing but paused — resuming');
        requestPlay();
        return;
      }

      // Playing but frozen
