      if (destroyed) return;
      destroyed = true;
      wantsPlay = false;
      players.delete(api);
      document.removeEventListener('visibilitychange', onVisibilityChange);
      root.removeEventListener('click', onClick);
      if (video) Object.keys(handlers).forEach((k) => video.removeEventListener(k, handlers[k]));
